// === Tab: mySketch ===
//Code by Aaron Reuland
//For the #wccChallenge on the theme of 'fireflies'.
//Particles light up and pull gently towards each other as they near.
//They also mix colors as they interact (using the Spectral.js library).
//To keep the colors from getting too monotonous they also have a small chance
//each frame to respawn in a random color from the color array.

//this array is an ode to indecisiveness
let palettes=[
["#cb417f","#e05ca4","#edc0dd","#deae94","#cbf7c2","#2b6860"],
["#2d4c61","#7a6074","#e7faa5","#ede070","#6ba6a8","#376c94"],
["#4ad3c8","#c69322","#c0bd9b","#a08b8d","#005e84","#42a5e4","#02c287"],
["#e70617","#c15a01","#458075","#57d0c9","#b7667d","#ee80b3","#b92b09"]
]

let fireFlies=[]
let fg, colors

function setup() {
	createCanvas(windowWidth, windowHeight);
	colors= random(palettes)
	shuffle(colors, true)

	for(let i=0; i<100; i++){
		fireFlies.push(new fireFly(random(width), random(height)))
	}

	fg= createGraphics(width, height)	
		fg.fill("#1A0C0D")
fg.noStroke()
	let gH= height/5
	for(let x=0; x<=width; x+=3){
	fg.beginShape()
	fg.vertex(x, height-height/20)
	let xoff1= random(-gH, gH)
	let yoff1= random(-gH/2, gH/2)
	let xoff2= random(-gH, gH)
	let yoff2= random(-gH/2, gH/2)
	let topXOff= random(-gH/2, gH/2)
	fg.bezierVertex(x+xoff1, height-yoff1, x+xoff2, height-yoff2, x+topXOff, height-gH+ random(-gH/4, gH/4))
	fg.bezierVertex(x+xoff2+20, height-yoff2, x+xoff1+20, height-yoff1, x+20, height-height/20)	
	fg.endShape(CLOSE)
	}	
}

function draw() {
	let bgColor= color("#1c0c0e")
	bgColor.setAlpha(100)
	background(bgColor)
	for(let f of fireFlies){
		f.update();
		f.relate();
		f.mutate();
		f.display();
	}

image(fg, 0, height/10)	

}

class fireFly{
	constructor(x, y){
		this.pos=createVector(x, y)
		this.color= random(colors)
		this.vel= createVector(0, 0)
    this.acc= p5.Vector.random2D();
		this.acc.setMag(0.01)
		this.lit=0
		this.newColor=NaN
		this.angle=this.vel.heading()
	}

	 update(){
    this.acc.setMag(0.015)
    this.vel.add(this.acc)
		 this.vel.limit(1)
    this.pos.add(this.vel)
    this.angle=this.vel.heading()

    //edges
    if(this.pos.x<-10){
      this.pos.x=width+10
    }
    if(this.pos.x>width+10){
      this.pos.x=-10
    }
    if(this.pos.y<-10){
      this.pos.y=height+10
    }
    if(this.pos.y>height+10){
      this.pos.y=-10
    }

  }

 relate(){
    for(let j=0; j<fireFlies.length; j++){
			let index = fireFlies.indexOf(this)
      let distance = p5.Vector.dist(this.pos, fireFlies[j].pos)
      if(distance < 30 && j!==index){

       //  this.pos.rotate(0.003)
				if(this.lit>50){
				let force= p5.Vector.sub(fireFlies[j].pos, this.pos)
				let forceMag= map(distance, 30, 0, 0.001, 0.01)
				force.setMag(forceMag)
				this.acc.add(force)
				}

				if(this.lit==0 && distance<20){
				this.lit=100
				}

				if(this.lit==100){
					let c1= fireFlies[j].color
					this.newColor=spectral.mix(c1, this.color, random(0.1, 0.9))

				}
			}	    
    }
	 if(this.lit==1){
		 this.color=this.newColor
	 }

  }

	mutate(){
		let r= random()
		if(r<0.0002){
		//	print('MUTANT!')
		let c= colorMixer(this.pos, colors)
		this.color=c
		}

	}

display(){


	if(this.lit>0){
		this.lit--
	}
	push()
	translate(this.pos.x, this.pos.y)
	rotate(this.angle)
	noStroke()
	fill(0)
	drawingContext.shadowBlur = 30;
  drawingContext.shadowColor = this.color;
	let colorAlpha= map(abs(this.lit-50), 0, 50, 255, 0)
	var c1= color(this.color)
	c1.setAlpha(colorAlpha)
	let c2= color(this.color)
	c2.setAlpha(0)
	push()
	let coloring= drawingContext.createRadialGradient(0, 0, 0.01, 0, 0, 20)
	  coloring.addColorStop(0, c1)
		coloring.addColorStop(0.9, c2)
		drawingContext.fillStyle= coloring
    ellipse(0, 0, 21, 19)
	pop()
	fill(c1)
	ellipse(0, 0, 7, 3)
	pop()
}

}

function colorMixer(pos, colorArray) {

	var c = noise(pos.x/200, pos.y/200)*colorArray.length
	var c1 = floor(c)
	var c2 = floor(c+1)%colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	var coloring = spectral.mix(color1, color2, mix)
	return coloring
}

